from abc import ABC, abstractmethod
import pandas as pd
import numpy as np
import datetime
from typing import List, Dict, Any

class BaseBankParser(ABC):
    """
    Abstract Base Class for all bank statement parsers.
    Ensures that every module returns data in the Universal Financial Format.
    """

    @property
    @abstractmethod
    def bank_name(self) -> str:
        pass

    @abstractmethod
    def parse(self, file_path: str) -> List[Dict[str, Any]]:
        """
        Parses the file and returns a list of dictionaries 
        matching the Transaction database model.
        """
        pass

    def standardize_dataframe(self, df: pd.DataFrame, mapping: Dict[str, str]) -> pd.DataFrame:
        """Helper to rename columns and ensure UFF (Universal Financial Format)."""
        return df.rename(columns=mapping)

    def sanitize_for_json(self, data: Dict[str, Any]) -> Dict[str, Any]:
        """
        Recursively converts dates, timestamps and NaNs into JSON-serializable formats.
        """
        sanitized = {}
        for key, value in data.items():
            # Check for various date/time types using the datetime module safely
            if isinstance(value, (datetime.datetime, datetime.date, pd.Timestamp)):
                sanitized[key] = value.isoformat()
            elif isinstance(value, float) and (np.isnan(value) or np.isinf(value)):
                sanitized[key] = None
            elif isinstance(value, dict):
                sanitized[key] = self.sanitize_for_json(value)
            elif isinstance(value, list):
                sanitized[key] = [
                    self.sanitize_for_json(v) if isinstance(v, dict) else v 
                    for v in value
                ]
            else:
                sanitized[key] = value
        return sanitized

import pdfplumber
import re
import datetime
import os
import sys
from typing import Dict, Any, List, Optional
from io import BytesIO
import base64

try:
    import pytesseract
    from PIL import Image
    from img2table.document import Image as IMG2TableImage
    from img2table.ocr import TesseractOCR
    HAS_OCR = True

    # Windows Tesseract Path Fix
    if sys.platform.startswith('win'):
        tesseract_paths = [
            r"C:\Program Files\Tesseract-OCR\tesseract.exe",
            r"C:\Program Files (x86)\Tesseract-OCR\tesseract.exe",
            os.path.join(os.getenv('LOCALAPPDATA', ''), r'Tesseract-OCR\tesseract.exe')
        ]
        for path in tesseract_paths:
            if os.path.exists(path):
                pytesseract.pytesseract.tesseract_cmd = path
                break
except ImportError:
    HAS_OCR = False

class GenericPDFParser:
    """
    Generic Parser that executes a user-defined template configuration.
    Supports freeform regions and multiple extraction strategies.
    """

    @staticmethod
    def parse_italian_float(val: str, force_sign: Optional[str] = None) -> float:
        if not val: return 0.0
        val = str(val).strip()
        # Handle cases where "-" might be at the end
        if val.endswith("-"): val = '-' + val[:-1]

        # Clean non-numeric except decimal/thousand separators
        clean = val.replace(".", "").replace(",", ".")
        try:
            num = float(clean)
            if force_sign == 'positive': return abs(num)
            if force_sign == 'negative': return -abs(num)
            return num
        except ValueError:
            return 0.0

    @classmethod
    def get_page_count(cls, file_path: str) -> int:
        with pdfplumber.open(file_path) as pdf:
            return len(pdf.pages)

    @classmethod
    def _get_ocr_words(cls, image: Any, offset_x: float = 0, offset_y: float = 0) -> List[Dict[str, Any]]:
        if not HAS_OCR: return []
        data = pytesseract.image_to_data(image, output_type=pytesseract.Output.DICT)
        words = []
        n_boxes = len(data['text'])
        for i in range(n_boxes):
            if int(data['conf'][i]) > 0 and data['text'][i].strip():
                x = data['left'][i] + offset_x
                y = data['top'][i] + offset_y
                w = data['width'][i]
                h = data['height'][i]
                words.append({
                    "x0": x,
                    "top": y,
                    "x1": x + w,
                    "bottom": y + h,
                    "text": data['text'][i]
                })
        return words

    @classmethod
    def preview(cls, file_path: str, config: Dict[str, Any], page_num: int = 0) -> Dict[str, Any]:
        """
        Runs parsing on a specific page using the provided stage or legacy config.
        """
        extracted_data = {}
        debug_image_b64 = None

        stages = config.get("stages", [])
        active_stage_id = config.get("active_stage_id")

        regions = []
        if stages:
            stage = next((s for s in stages if s['id'] == active_stage_id), stages[0])
            regions = stage.get("regions", [])
        else:
            regions = config.get("regions", [])

        with pdfplumber.open(file_path) as pdf:
            if page_num >= len(pdf.pages):
                return {"error": "Page index out of range"}

            page = pdf.pages[page_num]
            width, height = page.width, page.height

            # --- 1. Extract Data from Regions ---
            for region in regions:
                x0 = (region['x'] / 100.0) * width
                top = (region['y'] / 100.0) * height
                w_px = (region['w'] / 100.0) * width
                h_px = (region['h'] / 100.0) * height
                x1 = x0 + w_px
                bottom = top + h_px

                crop_box = (max(0, x0), max(0, top), min(width, x1), min(height, bottom))

                try:
                    cropped = page.crop(crop_box)
                    method = region.get('extractionMethod', 'text')

                    if region['type'] == 'table':
                        table_mode = region.get('tableExtractionMode', 'manual')
                        if method == 'ocr' and HAS_OCR:
                            crop_img = cropped.to_image(resolution=300).original
                            if table_mode == 'auto':
                                # Use img2table for intelligent detection
                                img_byte_arr = BytesIO()
                                crop_img.save(img_byte_arr, format='PNG')
                                img_byte_arr.seek(0)

                                ocr = TesseractOCR(n_threads=1, lang="ita")
                                doc = IMG2TableImage(img_byte_arr)
                                extracted_tables = doc.extract_tables(ocr=ocr, implicit_rows=True, borderless_tables=True, min_confidence=50)

                                if extracted_tables:
                                    df = extracted_tables[0].df
                                    df = df.fillna("")
                                    extracted_data[region['name']] = df.to_dict(orient='records')
                                else:
                                    # Fallback to simple line dump
                                    raw_text = pytesseract.image_to_string(crop_img).strip()
                                    lines = [l.strip() for l in raw_text.split('\n') if l.strip()]
                                    extracted_data[region['name']] = [{"row_text": l} for l in lines]
                            else:
                                words = cls._get_ocr_words(crop_img, offset_x=x0, offset_y=top)
                                extracted_data[region['name']] = cls._extract_table(words, region.get('columns', []), region_width=w_px, offset_x=x0)
                        else:
                            words = cropped.extract_words(keep_blank_chars=False, x_tolerance=3, y_tolerance=3)
                            extracted_data[region['name']] = cls._extract_table(words, region.get('columns', []), region_width=w_px, offset_x=x0)

                    elif region['type'] == 'text':
                        if method == 'ocr' and HAS_OCR:
                            crop_img = cropped.to_image(resolution=300).original
                            extracted_data[region['name']] = pytesseract.image_to_string(crop_img).strip()
                        else:
                            extracted_data[region['name']] = cropped.extract_text()

                    elif region['type'] == 'key_value':
                        fields = region.get('fields', [])
                        if fields:
                            field_results = {}
                            for field in fields:
                                fx = x0 + (field['x'] / 100.0) * w_px
                                ftop = top + (field['y'] / 100.0) * h_px
                                fw = (field['w'] / 100.0) * w_px
                                fh = (field['h'] / 100.0) * h_px
                                f_crop_box = (fx, ftop, fx + fw, ftop + fh)
                                f_cropped = page.crop(f_crop_box)

                                if method == 'ocr' and HAS_OCR:
                                    f_img = f_cropped.to_image(resolution=300).original
                                    field_results[field['name']] = pytesseract.image_to_string(f_img).strip()
                                else:
                                    field_results[field['name']] = f_cropped.extract_text(x_tolerance=0.1, y_tolerance=0.1)
                            extracted_data[region['name']] = field_results
                        else:
                            label = region.get('key_label') or region['name']
                            if method == 'ocr' and HAS_OCR:
                                crop_img = cropped.to_image(resolution=300).original
                                extracted_data[label] = pytesseract.image_to_string(crop_img).strip()
                            else:
                                extracted_data[label] = cropped.extract_text(x_tolerance=0.1, y_tolerance=0.1)
                except Exception as e:
                    extracted_data[region['name']] = f"Error: {str(e)}"

            # --- 2. Generate Debug Image ---
            im = page.to_image(resolution=150)

            for region in regions:
                x0 = (region['x'] / 100.0) * width
                top = (region['y'] / 100.0) * height
                w_px = (region['w'] / 100.0) * width
                h_px = (region['h'] / 100.0) * height
                x1 = x0 + w_px
                bottom = top + h_px

                color = "green" if region['type'] == 'table' else "red" if region['type'] == 'text' else "blue"
                im.draw_rect((x0, top, x1, bottom), fill=None, stroke=color, stroke_width=3)

                if region['type'] == 'table':
                    # Hide columns if auto mode
                    if region.get('tableExtractionMode') != 'auto':
                        for col in region.get('columns', []):
                            cx = (col.get('x', 0) / 100.0) * width
                            im.draw_line([(cx, top), (cx, bottom)], stroke="purple", stroke_width=2)

                if region['type'] == 'key_value' and region.get('fields'):
                    for field in region['fields']:
                        fx = x0 + (field['x'] / 100.0) * w_px
                        ftop = top + (field['y'] / 100.0) * h_px
                        fw = (field['w'] / 100.0) * w_px
                        fh = (field['h'] / 100.0) * h_px
                        im.draw_rect((fx, ftop, fx + fw, ftop + fh), fill=None, stroke="cyan", stroke_width=1)

            buffer = BytesIO()
            im.save(buffer, format="PNG")
            debug_image_b64 = base64.b64encode(buffer.getvalue()).decode()

        return {
            "extracted_data": extracted_data,
            "debug_image": debug_image_b64,
            "page_count": len(pdf.pages)
        }

    @classmethod
    def parse(cls, file_path: str, config: Dict[str, Any]) -> Dict[str, Any]:
        """
        Executes the full parsing flow across all pages.
        """
        results = {}
        stages = config.get("stages", [])

        if not stages:
            legacy_regions = config.get("regions", [])
            stages = [{"id": "legacy", "name": "Legacy Stage", "regions": legacy_regions, "transitions": []}]
            current_stage_id = "legacy"
        else:
            current_stage_id = config.get("start_stage_id") or stages[0]["id"]

        with pdfplumber.open(file_path) as pdf:
            width, height = pdf.pages[0].width, pdf.pages[0].height # Assume consistent size

            for page_idx, page in enumerate(pdf.pages):
                current_stage = next((s for s in stages if s["id"] == current_stage_id), stages[0])

                for region in current_stage.get("regions", []):
                    rx0 = (region['x'] / 100.0) * width
                    rtop = (region['y'] / 100.0) * height
                    rw = (region['w'] / 100.0) * width
                    rh = (region['h'] / 100.0) * height

                    crop_box = (rx0, rtop, rx0 + rw, rtop + rh)

                    try:
                        cropped = page.crop(crop_box)
                        name = region['name']
                        method = region.get('extractionMethod', 'text')

                        extracted = None
                        if region['type'] == 'table':
                            table_mode = region.get('tableExtractionMode', 'manual')
                            if method == 'ocr' and HAS_OCR:
                                crop_img = cropped.to_image(resolution=300).original
                                if table_mode == 'auto':
                                    # Use img2table for intelligent detection
                                    img_byte_arr = BytesIO()
                                    crop_img.save(img_byte_arr, format='PNG')
                                    img_byte_arr.seek(0)

                                    ocr = TesseractOCR(n_threads=1, lang="ita")
                                    doc = IMG2TableImage(img_byte_arr)
                                    extracted_tables = doc.extract_tables(ocr=ocr, implicit_rows=True, borderless_tables=True, min_confidence=50)

                                    if extracted_tables:
                                        df = extracted_tables[0].df
                                        df = df.fillna("")
                                        extracted = df.to_dict(orient='records')
                                    else:
                                        raw_text = pytesseract.image_to_string(crop_img).strip()
                                        lines = [l.strip() for l in raw_text.split('\n') if l.strip()]
                                        extracted = [{"row_text": l} for l in lines]
                                else:
                                    words = cls._get_ocr_words(crop_img, offset_x=rx0, offset_y=rtop)
                                    extracted = cls._extract_table(words, region.get('columns', []), region_width=rw, offset_x=rx0)
                            else:
                                words = cropped.extract_words(keep_blank_chars=False, x_tolerance=3, y_tolerance=3)
                                extracted = cls._extract_table(words, region.get('columns', []), region_width=rw, offset_x=rx0)

                        elif region['type'] == 'text':
                            if method == 'ocr' and HAS_OCR:
                                crop_img = cropped.to_image(resolution=300).original
                                extracted = pytesseract.image_to_string(crop_img).strip()
                            else:
                                extracted = cropped.extract_text()

                        elif region['type'] == 'key_value':
                            fields = region.get('fields', [])
                            if fields:
                                extracted = {}
                                for field in fields:
                                    fx = rx0 + (field['x'] / 100.0) * rw
                                    ftop = rtop + (field['y'] / 100.0) * rh
                                    fw = (field['w'] / 100.0) * rw
                                    fh = (field['h'] / 100.0) * rh
                                    f_cropped = page.crop((fx, ftop, fx + fw, ftop + fh))

                                    if method == 'ocr' and HAS_OCR:
                                        f_img = f_cropped.to_image(resolution=300).original
                                        extracted[field['name']] = pytesseract.image_to_string(f_img).strip()
                                    else:
                                        extracted[field['name']] = f_cropped.extract_text(x_tolerance=0.1, y_tolerance=0.1)
                            else:
                                name = region.get('key_label') or region['name']
                                if method == 'ocr' and HAS_OCR:
                                    crop_img = cropped.to_image(resolution=300).original
                                    extracted = pytesseract.image_to_string(crop_img).strip()
                                else:
                                    extracted = cropped.extract_text(x_tolerance=0.1, y_tolerance=0.1)

                        if isinstance(extracted, list):
                            if name not in results: results[name] = []
                            results[name].extend(extracted)
                        elif isinstance(extracted, dict):
                            # Merge KV fields
                            if name not in results: results[name] = {}
                            results[name].update(extracted)
                        else:
                            if name not in results: results[name] = extracted
                            else: results[name] = f"{results[name]}\n{extracted}"

                    except Exception: continue

                page_text = page.extract_text() or ""
                for trans in current_stage.get("transitions", []):
                    if cls._check_condition(trans, page_idx, page_text):
                        if trans["action"] == "stop": return results
                        elif trans["action"] == "next_stage":
                            current_stage_id = trans["targetId"]
                            break

        return results

    @staticmethod
    def _check_condition(trans: Dict, page_idx: int, page_text: str) -> bool:
        cond = trans["condition"]
        val = trans["value"]
        if cond == "always": return True
        if cond == "text": return val.lower() in page_text.lower()
        if cond == "regex":
            try: return bool(re.search(val, page_text, re.IGNORECASE))
            except Exception: return False
        if cond == "index": return str(page_idx) == str(val)
        return False

    @classmethod
    def _extract_table(cls, words: List[Dict], columns: List[Dict], region_width: float, offset_x: float = 0.0) -> List[Dict[str, Any]]:
        """
        Extracts rows based on percentage-based columns (relative to region width).
        """
        rows = []
        if not words: return []

        # Sort columns by percentage X (region-relative)
        columns = sorted(columns, key=lambda c: c['x'])

        lines = {}
        for w in words:
            y = round(w["top"] / 4) * 4
            if y not in lines: lines[y] = []
            lines[y].append(w)

        sorted_y = sorted(lines.keys())
        for y in sorted_y:
            line_words = sorted(lines[y], key=lambda w: w["x0"])
            row_data = {col['name']: "" for col in columns}

            for w in line_words:
                cx = (w["x0"] + w["x1"]) / 2

                matched_col = None
                for i, col in enumerate(columns):
                    col_abs_start = offset_x + (col['x'] / 100.0) * region_width

                    next_col_abs_start = 99999
                    if i < len(columns) - 1:
                        next_col_abs_start = offset_x + (columns[i+1]['x'] / 100.0) * region_width

                    if col_abs_start <= cx < next_col_abs_start:
                        matched_col = col
                        break

                if matched_col:
                    row_data[matched_col['name']] = (row_data[matched_col['name']] + " " + w["text"]).strip()

            clean_row = {}
            has_data = False
            for col in columns:
                raw = row_data[col['name']]
                if raw: has_data = True

                if col.get('type') == 'currency' or col.get('type') == 'float':
                    clean_row[col['name']] = cls.parse_italian_float(raw, force_sign=col.get('sign'))
                else:
                    clean_row[col['name']] = raw

            if has_data: rows.append(clean_row)
        return rows

