    @staticmethod
    def parse_italian_float(val: str, force_sign: Optional[str] = None) -> float:
        if not val: return 0.0
        val = str(val).strip()
        # Handle cases where "-" might be at the end
        if val.endswith("-"): val = '-' + val[:-1]

        # Clean non-numeric except decimal/thousand separators
        clean = val.replace(".", "").replace(",", ".")
        try:
            num = float(clean)
            if force_sign == 'positive': return abs(num)
            if force_sign == 'negative': return -abs(num)
            return num
        except ValueError:
            return 0.0

