        base_config = "--oem 1" # LSTM engine

        if user_psm is not None:
            return f"{base_config} --psm {user_psm}"

        if region_type == 'table_cell':
            return f"{base_config} --psm 7" # Single text line
        elif region_type == 'key_value':
            return f"{base_config} --psm 6" # Single uniform block
        elif region_type == 'text':
