class GenericPDFParser:
    """
    Generic Parser that executes a user-defined template configuration.
    Supports freeform regions and multiple extraction strategies.
    """

    @staticmethod
    def parse_italian_float(val: str, force_sign: Optional[str] = None) -> float:
        if not val: return 0.0
        val = str(val).strip()
        # Handle cases where "-" might be at the end
        if val.endswith("-"): val = '-' + val[:-1]

        # Clean non-numeric except decimal/thousand separators
        clean = val.replace(".", "").replace(",", ".")
        try:
            num = float(clean)
            if force_sign == 'positive': return abs(num)
            if force_sign == 'negative': return -abs(num)
            return num
        except ValueError:
            return 0.0

    @classmethod
    def get_page_count(cls, file_path: str) -> int:
        with pdfplumber.open(file_path) as pdf:
            return len(pdf.pages)

    @classmethod
    def _preprocess_image(cls, image: Any) -> Any:
        """
        Applies grayscale and thresholding to improve OCR accuracy.
        """
        if not HAS_OCR: return image
        try:
            # Convert PIL to OpenCV
            img_np = np.array(image)

            # Convert RGB to BGR/Gray
            if len(img_np.shape) == 3:
                gray = cv2.cvtColor(img_np, cv2.COLOR_RGB2GRAY)
            else:
                gray = img_np

            # Apply Otsu's thresholding
            _, binary = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)

            # Convert back to PIL
            return Image.fromarray(binary)
        except Exception:
            return image

