                                for field in fields:
                                    fx = rx0 + (field['x'] / 100.0) * rw
                                    ftop = rtop + (field['y'] / 100.0) * rh
                                    fw = (field['w'] / 100.0) * rw
                                    fh = (field['h'] / 100.0) * rh
                                    f_cropped = page.crop((fx, ftop, fx + fw, ftop + fh))

                                    if method == 'ocr' and HAS_OCR:
                                        f_img = f_cropped.to_image(resolution=300).original
                                        extracted[field['name']] = pytesseract.image_to_string(f_img).strip()
                                    else:
                                        extracted[field['name']] = f_cropped.extract_text(x_tolerance=0.1, y_tolerance=0.1)
                            else:
                                name = region.get('key_label') or region['name']
                                if method == 'ocr' and HAS_OCR:
                                    crop_img = cropped.to_image(resolution=300).original
                                    extracted = pytesseract.image_to_string(crop_img).strip()
                                else:
                                    extracted = cropped.extract_text(x_tolerance=0.1, y_tolerance=0.1)

                        if isinstance(extracted, list):
                            if name not in results: results[name] = []
                            results[name].extend(extracted)
                        elif isinstance(extracted, dict):
                            # Merge KV fields
                            if name not in results: results[name] = {}
                            results[name].update(extracted)
                        else:
                            if name not in results: results[name] = extracted
                            else: results[name] = f"{results[name]}\n{extracted}"

