                for trans in current_stage.get("transitions", []):
                    if cls._check_condition(trans, page_idx, page_text):
                        if trans["action"] == "stop": return results
                        elif trans["action"] == "next_stage":
                            current_stage_id = trans["targetId"]
                            break

        return results

    @staticmethod
    def _check_condition(trans: Dict, page_idx: int, page_text: str) -> bool:
        cond = trans["condition"]
        val = trans["value"]
        if cond == "always": return True
        if cond == "text": return val.lower() in page_text.lower()
        if cond == "regex":
            try: return bool(re.search(val, page_text, re.IGNORECASE))
            except Exception: return False
        if cond == "index": return str(page_idx) == str(val)
        return False

    @classmethod
    def _extract_table(cls, words: List[Dict], columns: List[Dict], region_width: float, offset_x: float = 0.0) -> List[Dict[str, Any]]:
        """
        Extracts rows based on percentage-based columns (relative to region width).
        """
        rows = []
        if not words: return []

        # Sort columns by percentage X (region-relative)
        columns = sorted(columns, key=lambda c: c['x'])

        lines = {}
        for w in words:
            y = round(w["top"] / 4) * 4
            if y not in lines: lines[y] = []
            lines[y].append(w)

        sorted_y = sorted(lines.keys())
        for y in sorted_y:
            line_words = sorted(lines[y], key=lambda w: w["x0"])
            row_data = {col['name']: "" for col in columns}

            for w in line_words:
                cx = (w["x0"] + w["x1"]) / 2

                matched_col = None
                for i, col in enumerate(columns):
                    col_abs_start = offset_x + (col['x'] / 100.0) * region_width

                    next_col_abs_start = 99999
                    if i < len(columns) - 1:
                        next_col_abs_start = offset_x + (columns[i+1]['x'] / 100.0) * region_width

                    if col_abs_start <= cx < next_col_abs_start:
                        matched_col = col
                        break

                if matched_col:
                    row_data[matched_col['name']] = (row_data[matched_col['name']] + " " + w["text"]).strip()

            clean_row = {}
            has_data = False
            for col in columns:
                raw = row_data[col['name']]
                if raw: has_data = True

                if col.get('type') == 'currency' or col.get('type') == 'float':
                    clean_row[col['name']] = cls.parse_italian_float(raw, force_sign=col.get('sign'))
                else:
                    clean_row[col['name']] = raw

            if has_data: rows.append(clean_row)
        return rows

