    @classmethod
    def _preprocess_image(cls, image: Any) -> Any:
        """
        Applies grayscale and thresholding to improve OCR accuracy.
        """
        if not HAS_OCR: return image
        try:
            # Convert PIL to OpenCV
            img_np = np.array(image)

            # Convert RGB to BGR/Gray
            if len(img_np.shape) == 3:
                gray = cv2.cvtColor(img_np, cv2.COLOR_RGB2GRAY)
            else:
                gray = img_np

            # Apply Otsu's thresholding
            _, binary = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)

            # Convert back to PIL
            return Image.fromarray(binary)
        except Exception:
            return image

    @classmethod
    def _get_tesseract_config(cls, region_type: str, user_psm: Optional[int] = None) -> str:
